#include <stdio.h>
#include "tray.h"

static int read_digit(void)
{
    int symbol = getchar();
    if (symbol < '0' || symbol > '9') {
        return -1;
    }
    int tail = getchar();
    return tail == '\n' || tail == EOF ? symbol - '0' : -1;
}

int main(void)
{
    int items = read_digit();
    if (items < 0) {
        puts("invalid");
        return 1;
    }
    printf("trays=%d\n", trays_needed(items));
    return 0;
}

